class TrieNode:
    def __init__(self):
        self.children = {}
        self.value = 0

class MapSum:
    def __init__(self):
        self.root = TrieNode()
        self.map = {}

    def insert(self, key, val):
        delta = val - self.map.get(key, 0)               # compute the CHANGE in value
        self.map[key] = val
        node = self.root
        node.value += delta
        for c in key:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
            node.value += delta                             # propagate delta along the path

    def sum(self, prefix):
        node = self.root
        for c in prefix:
            if c not in node.children:
                return 0
            node = node.children[c]
        return node.value                                     # O(1) cached lookup

