#include <bits/stdc++.h>
using namespace std;

struct TrieNode { unordered_map<char, TrieNode*> children; int value = 0; };

class MapSum {
public:
    TrieNode* root = new TrieNode();
    unordered_map<string, int> keyMap;

    void insert(string key, int val) {
        int delta = val - (keyMap.count(key) ? keyMap[key] : 0);        // compute the CHANGE in value
        keyMap[key] = val;
        TrieNode* node = root;
        node->value += delta;
        for (char c : key) {
            if (!node->children.count(c)) node->children[c] = new TrieNode();
            node = node->children[c];
            node->value += delta;                                          // propagate delta along the path
        }
    }

    int sum(string prefix) {
        TrieNode* node = root;
        for (char c : prefix) {
            if (!node->children.count(c)) return 0;
            node = node->children[c];
        }
        return node->value;                                                  // O(1) cached lookup
    }
};
